async function start(){try{const sel=episodes.filter(ep=>selected().includes(ep.source)&&ep.status!=='ALREADY_TRANSLATED');if(!sel.length)return notify('Selecione pelo menos um episódio sem PT-BR.','warn');const source_languages={};sel.forEach(ep=>{const key=episodeKey(ep);const el=langSelects[key];source_languages[ep.source]=el?el.value:globalSourceLang});const preview=await api('/preflight',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder:selectedFolder,episodes:sel.map(ep=>ep.source),source_languages})});if(!await showTranslationPreflight(preview))return;await api('/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder:selectedFolder,episodes:sel.map(ep=>ep.source),source_languages,dry_run:$('dryrun').checked})});notify($('dryrun').checked?'Simulação enfileirada. Nenhum modelo será chamado.':`${sel.length} episódio${sel.length===1?'':'s'} enviado${sel.length===1?'':'s'} para a fila.`,'ok');await refresh(true)}catch(e){notify(e.message,'fail')}}
