 // A primeira carga costumava enviar o idioma global (inglês) antes de
 // descobrir que a temporada só possui tracks francesas. A declaração abaixo
 // substitui a versão anterior por uma versão que autodetecta o idioma da
 // primeira fonte; uma escolha manual posterior continua sendo respeitada.
 async function loadEpisodes(){
  if(!selectedFolder){episodes=[];$('episodes').innerHTML='<div class="empty-state"><b>Nenhuma temporada carregada</b>Escolha uma pasta e clique em “Carregar esta temporada”.</div>';syncSelectionUi();return}
  if(selectionFolder!==selectedFolder){selectedEpisodeKeys.clear();selectionFolder=selectedFolder}
  const lang=seasonLangValue||globalSourceLang;
  const d=await api('/episodes?path='+encodeURIComponent(selectedFolder)+'&source_language='+encodeURIComponent(lang)+'&offset=0&limit=40');
  episodes=d.episodes;episodeOffset=d.offset||0;episodeHasMore=Boolean(d.has_more);if($('loadMoreEpisodes')){$('loadMoreEpisodes').hidden=!episodeHasMore;$('loadMoreEpisodes').disabled=!episodeHasMore}
  lastEpisodesRefreshAt=Date.now();
  const detectedFolder=globalThis.__subtranslateDetectedSourceFolder||'';
  if(detectedFolder!==selectedFolder){
   globalThis.__subtranslateDetectedSourceFolder=selectedFolder;
   const first=episodes.find(ep=>ep.source);
   if(first){
    try{
     const options=await api('/source-options?path='+encodeURIComponent(first.source));
     const languages=Array.from(new Set((options.options||[]).map(o=>o.language).filter(Boolean)));
     const detected=languages.includes(lang)?lang:languages[0];
     if(detected&&detected!==lang){
      seasonLangValue=detected;
      const season=$('seasonLang');
      if(season&&!Array.from(season.options).some(o=>o.value===detected)){
       const option=document.createElement('option');option.value=detected;option.textContent=detected;season.append(option)
      }
      if(season)season.value=detected;
      return loadEpisodes();
     }
    }catch(e){console.warn('source autodetect',e)}
   }
  }
  const valid=new Set(episodes.map(episodeKey));
  selectedEpisodeKeys=new Set([...selectedEpisodeKeys].filter(key=>valid.has(key)));
  const fingerprint=JSON.stringify(episodes.map(ep=>[episodeKey(ep),ep.status,ep.audit_status,ep.ptbr,ep.source_status]));
  if(fingerprint!==episodeRenderFingerprint){episodeRenderFingerprint=fingerprint;renderEpisodes()}else syncSelectionUi()
 }

 async function loadMoreEpisodes(){if(!selectedFolder||!episodeHasMore||episodeLoading)return;episodeLoading=true;const button=$('loadMoreEpisodes');if(button)button.disabled=true;try{const nextOffset=episodes.length;const d=await api('/episodes?path='+encodeURIComponent(selectedFolder)+'&source_language='+encodeURIComponent(seasonLangValue||globalSourceLang)+'&offset='+nextOffset+'&limit=40');episodes=episodes.concat(d.episodes||[]);episodeOffset=episodes.length;episodeHasMore=Boolean(d.has_more);episodeRenderFingerprint='';renderEpisodes()}catch(e){notify('Não foi possível carregar mais episódios: '+e.message,'fail')}finally{episodeLoading=false;if(button){button.disabled=!episodeHasMore;button.hidden=!episodeHasMore}}}

 let currentArchiveSeriesId=null;
function recordValidated(record){return ['VALIDATED','OK','PUBLISHED'].includes(String(record.validation_status||'').toUpperCase())}
function recordPublished(record){return record.published===true||record.publication_status==='PUBLISHED'||(record.publications||[]).some(item=>item.status==='PUBLISHED')}
function recordLabel(record){if(record.pipeline_version)return record.pipeline_version;const k=(record.source_kind||'').toUpperCase();if(k==='IMPORTED_EXISTING')return 'Versão legada';if(k==='EXTRACTED')return 'Fonte extraída';return 'Pipeline desconhecido'}
function recordAuditLabel(record){const status=record.audit_status||record.audit?.status,flags=record.audit?.flags||[];if(status==='REVISÃO RECOMENDADA'||(status==='PROBLEMAS DETECTADOS'&&flags.length&&flags.every(flag=>flag==='POSSIBLE_UNTRANSLATED_OUTPUT')))return '◐ possível resíduo · revisar';if(status==='PROBLEMAS DETECTADOS')return '⚠ problemas nesta versão';if(status==='SEM PROBLEMAS DETECTADOS')return '✓ sem problemas nesta versão';if(recordValidated(record))return '✓ validada';return status||'não auditada'}
function recordPreferred(record, preferredRecordId){return preferredRecordId!=null?String(preferredRecordId)===String(record.id):Boolean(record.preferred)}
function recordSidecarCurrent(record){return record.target_present===true&&record.target_record_id!=null&&String(record.target_record_id)===String(record.id)}
function recordStateBadge(record, preferredRecordId){
 const published=recordPublished(record),sidecarCurrent=recordSidecarCurrent(record),badges=[];
 if(published&&sidecarCurrent)badges.push('<span class="badge ok" title="Versão publicada e correspondente à legenda atual no disco">✓ ATUAL PUBLICADA</span>');
 else if(published)badges.push('<span class="badge ok">✓ PUBLICADA</span>');
 else if(recordValidated(record))badges.push('<span class="badge wait">NÃO PUBLICADA</span>');
 else badges.push('<span class="badge neutral">'+esc(record.validation_status||'não validada')+'</span>');
 if(recordPreferred(record,preferredRecordId))badges.push('<span class="badge" title="Versão selecionada como referência atual do episódio">★ VERSÃO PREFERIDA</span>');
 if(sidecarCurrent&&!published)badges.push('<span class="badge ok" title="O arquivo .pt-BR do episódio corresponde a esta versão">◉ LEGENDA ATUAL</span>');
 if(record.target_present===true&&record.target_record_id==null&&(
   preferredRecordId==null||recordPreferred(record,preferredRecordId)
 ))badges.push('<span class="badge wait" title="Existe uma legenda .pt-BR no disco, mas ela não corresponde a nenhuma versão do Acervo">⚠ LEGENDA ATUAL NÃO CATALOGADA</span>');
 if(published&&!record.target_present)badges.push('<span class="badge fail" title="A publicação está registrada, mas a legenda não foi encontrada no disco">⚠ LEGENDA AUSENTE</span>');
 if(published&&record.target_present===true&&record.target_record_id!=null&&!sidecarCurrent)badges.push('<span class="badge fail" title="A legenda atual tem conteúdo diferente desta versão publicada">⚠ CONFLITO NA LEGENDA</span>');
 return badges.join(' ');
}
function versionDetailsHtml(record){
 const lineage=record.lineage||[];
 const parent=lineage.find(item=>String(item.source_record_id)===String(record.id)&&item.parent_record_id!=null);
 const sourceText=parent?`Inglês · registro ${parent.parent_record_id}`:(record.source_language||'não informada');
 const published=recordPublished(record);
 const publication=record.publication||(record.publications||[]).find(item=>item.status==='PUBLISHED');
 const targetState=record.target_present?(record.target_record_id?`legenda atual: registro ${record.target_record_id}`:'legenda atual: versão não catalogada'):'nenhuma legenda atual ao lado do vídeo';
 const events=record.events_total!=null?`${esc(record.events_total)}/${esc(record.events_total)}`:'não informado';
 const validation=recordValidated(record);
 return `<div class="note"><b>${esc(record.series_title||'Anime')} · S${esc(record.season||'—')}E${esc(record.episode||'—')} — ${esc(record.episode_title||record.media_filename||'Episódio')}</b></div><div class="row" style="margin-top:10px;gap:6px"><span class="badge">${esc(recordLabel(record))}</span><span class="badge">${esc(record.language||'—')}</span><span class="badge">${esc(record.source_kind||'—')}</span>${recordStateBadge(record)}</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px;margin-top:12px"><div class="stat"><b>Estado</b><span>${validation?'VALIDADA':'NÃO VALIDADA'}</span></div><div class="stat"><b>Modelo</b><span>${esc(record.model||'não informado')}</span></div><div class="stat"><b>Fonte</b><span>${esc(sourceText)}</span></div><div class="stat"><b>Eventos</b><span>${events}</span></div></div><div class="panel" style="margin-top:12px;padding:10px"><b>Validação</b><div class="muted" style="margin-top:5px">${validation?'✓ Estrutura registrada · ✓ conteúdo registrado · ✓ sem erros críticos registrados':'Validação técnica pendente ou incompatível'}</div><div style="margin-top:8px"><b>Publicação</b><div class="muted">${published?'✓ Publicada no Jellyfin'+(publication?.published_at?` · ${esc(publication.published_at)}`:''):'NÃO PUBLICADA'}</div><div class="muted">Destino: ${esc(targetState)}</div></div></div><details style="margin-top:10px"><summary>Detalhes técnicos</summary><dl style="display:grid;grid-template-columns:minmax(120px,auto) 1fr;gap:4px 12px;overflow-wrap:anywhere"><dt>Registro</dt><dd>${esc(record.id)}</dd><dt>Objeto</dt><dd>${esc(record.object_id)}</dd><dt>SHA-256</dt><dd>${esc(record.sha256||'—')}</dd><dt>Formato</dt><dd>${esc(record.format||'—')}</dd><dt>Registro de origem</dt><dd>${esc(parent?.parent_record_id||'—')}</dd><dt>Auditoria</dt><dd>${esc(record.audit_status||'NÃO AUDITADA')}</dd>${publication?`<dt>Destino</dt><dd>${esc(publication.target_relative_path||'—')}</dd>`:''}</dl></details><div class="record-actions" style="justify-content:flex-start;margin-top:14px">${validation&&!published?`<button class="button primary" data-modal-publish="${record.id}">Publicar no Jellyfin</button>`:''}<a class="button" href="/library/records/${record.id}/download">Baixar</a></div>`;
}
async function showVersionDetails(recordId){try{const record=await api('/library/records/'+recordId);$('versionDetailsTitle').textContent=`Detalhes · ${recordLabel(record)}`;$('versionDetailsSubtitle').textContent=`${record.language||'—'} · ${record.source_kind||'—'} · ${recordPublished(record)?'publicada':'não publicada'}`;$('versionDetailsBody').innerHTML=versionDetailsHtml(record);const dialog=$('versionDetailsDialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');dialog.querySelectorAll('[data-modal-publish]').forEach(button=>button.onclick=()=>publishRecord(Number(button.dataset.modalPublish)))}catch(e){alert('Não foi possível carregar os detalhes desta versão.')}}
async function publishRecord(recordId){try{const record=await api('/library/records/'+recordId);if(!recordValidated(record)){notify('Somente uma versão validada pode ser publicada.','warn');return}const episode=await api('/library/episodes/'+record.episode_id);const current=(episode.records||[]).find(item=>recordPublished(item))||(record.target_record_id?(episode.records||[]).find(item=>String(item.id)===String(record.target_record_id)):null);const currentLabel=current?`${recordLabel(current)} / registro ${current.id}`:(record.target_present?'legenda atual não catalogada':'nenhuma versão publicada');const newLabel=`${recordLabel(record)} / registro ${record.id}`;const currentHash=record.target_sha256||current?.sha256;const sameHash=currentHash&&currentHash===record.sha256;if(sameHash){notify('Esta versão já está publicada com o mesmo conteúdo.','ok');return}const different=Boolean(currentHash&&currentHash!==record.sha256);const message=`Publicar ${newLabel} para ${record.series_title||'Anime'} S${record.season||'—'}E${record.episode||'—'}?\n\nVersão atualmente publicada: ${currentLabel}\nNova versão: ${newLabel}\n\nA versão anterior continuará preservada no Acervo.`;if(!confirm(message))return;const result=await api('/library/records/'+recordId+'/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_replace:different})});$('versionDetailsDialog').close?.();if(currentArchiveSeriesId!=null)await openArchiveSeries(currentArchiveSeriesId);await loadArchive();notify(result.noop?'Esta versão já estava publicada.':`${recordLabel(record)} publicada no Jellyfin.`,'ok')}catch(e){notify(e.message||'Não foi possível publicar esta versão.','fail')}}
function versionRow(record, peers, preferredRecordId){const reviewable=String(record.language||'').toLowerCase()!=='eng';const peer=peers.find(item=>String(item.id)!==String(record.id));const compare=peer?`<button class="button" data-compare-old="${peer.id}" data-compare-new="${record.id}">Comparar</button>`:'';return `<div class="jobline" style="display:block;padding:11px 0"><div class="row" style="justify-content:space-between;align-items:flex-start"><div><b>${esc(recordLabel(record))}</b> <span class="badge">${esc(record.language||'—')}</span> <span class="badge">${esc(record.source_kind||'—')}</span> <span class="badge">${esc(record.validation_status||'—')}</span> ${recordStateBadge(record,preferredRecordId)}<div class="muted" style="margin-top:4px">${esc(recordAuditLabel(record))}</div></div><div class="record-actions" style="justify-content:flex-start">${recordValidated(record)&&!recordPublished(record)?`<button class="button primary" data-publish-record="${record.id}">Publicar no Jellyfin</button>`:''}<button class="button" data-details-record="${record.id}">Detalhes</button></div></div><details style="margin-top:8px"><summary>Mais ações</summary><div class="record-actions" style="justify-content:flex-start;margin-top:8px"><a class="button" href="/library/records/${record.id}/download">Baixar</a>${reviewable?`<a class="button" href="/review/${record.id}">Revisar</a>`:''}${compare}</div></details></div>`}
function episodeSidecarBadge(records){
 const target=records.find(item=>item.target_present===true);
 if(!target)return '<span class="badge neutral">SEM LEGENDA ATUAL</span>';
 if(target.target_record_id==null)return '<span class="badge wait" title="Existe um arquivo .pt-BR no disco, mas ele não corresponde a nenhuma versão do Acervo">⚠ LEGENDA ATUAL NÃO CATALOGADA</span>';
 const current=records.find(item=>String(item.id)===String(target.target_record_id));
 if(!current)return '<span class="badge fail" title="O Acervo aponta para uma versão que não está disponível nesta lista">⚠ LEGENDA INCONSISTENTE</span>';
 const published=recordPublished(current);
 return `<span class="badge ${published?'ok':'wait'}" title="Versão correspondente ao arquivo .pt-BR atualmente ao lado do vídeo">${published?'✓ ATUAL PUBLICADA':'◉ LEGENDA ATUAL'}: ${esc(recordLabel(current))} · registro ${esc(current.id)}</span>`;
}

function formatTimestamp(milliseconds){const value=Math.max(0,Number(milliseconds)||0),hours=Math.floor(value/3600000),minutes=Math.floor(value%3600000/60000),seconds=Math.floor(value%60000/1000),millis=Math.floor(value%1000);return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}.${String(millis).padStart(3,'0')}`}
async function showComparison(oldId,newId){const dialog=$('comparisonDialog'),body=$('comparisonBody');body.innerHTML='<div class="muted">Comparando versões…</div>';if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');try{const d=await api('/library/records/compare?old_id='+encodeURIComponent(oldId)+'&new_id='+encodeURIComponent(newId));$('comparisonSubtitle').textContent=`${d.changed_count||0} evento(s) alterado(s) · ${d.old_events||0} antes · ${d.new_events||0} depois`;body.innerHTML=(d.changed_events||[]).map(item=>`<article class="comparison-event"><div class="comparison-event-head"><b>Evento ${Number(item.event_id)+1}</b><span>${formatTimestamp(item.timestamp?.[0])} → ${formatTimestamp(item.timestamp?.[1])}</span></div><div class="comparison-columns"><div class="comparison-side old"><span>Antes</span><p>${esc(item.old_visible??item.old??'—')}</p></div><div class="comparison-side new"><span>Depois</span><p>${esc(item.new_visible??item.new??'—')}</p></div></div></article>`).join('')||'<div class="empty-state"><b>Nenhuma diferença encontrada</b><span>As duas versões possuem o mesmo texto visível.</span></div>'}catch(e){body.innerHTML=`<div class="note">Não foi possível comparar as versões: ${esc(e.message)}</div>`}}
$('closeComparison').onclick=()=>{$('comparisonDialog').close?.();$('comparisonDialog').removeAttribute('open')};$('comparisonDialog').addEventListener('click',event=>{if(event.target===$('comparisonDialog'))$('comparisonDialog').close?.()});

// Render the archive once, with publication, current-file and comparison data.
async function openArchiveSeries(id){
 currentArchiveSeriesId=id;
 const details=$('archiveDetails');if(details)details.textContent=t('library.detailLoading');
 try{
  const x=await api('/library/series/'+id+'?source_status=1');
  const header=`<div class="note"><b>${esc(x.title)}</b> · ${esc(x.classification)}<br><small>${x.episodes.length} episódios catalogados · versões agrupadas por episódio</small></div>`;
  const episodes=x.episodes.map(ep=>{
   const rs=ep.records||[],translated=rs.filter(item=>String(item.language||'').toLowerCase()!=='eng');
   const validated=translated.filter(recordValidated).length;
   const problems=translated.filter(item=>{const a=item.audit||{};return a.status==='PROBLEMAS DETECTADOS'&&!(a.flags||[]).every(flag=>flag==='POSSIBLE_UNTRANSLATED_OUTPUT')}).length;
   const possible=translated.filter(item=>(item.audit?.flags||[]).includes('POSSIBLE_UNTRANSLATED_OUTPUT')).length;
   const published=translated.filter(recordPublished).length;
   const summary=[`${rs.length} versões`,validated?`${validated} validada(s)`:null,problems?`${problems} com problemas (por versão)`:null,possible?`${possible} auditoria(s) com possível resíduo`:null,published?`${published} publicada(s)`:null].filter(Boolean).join(' · ');
   const sidecar=episodeSidecarBadge(rs);
   const pref=rs.find(r=>String(r.id)===String(ep.preferred_record_id))||rs.find(r=>r.preferred)||rs[0];
   const source=ep.source_status||{},sourceText=source.display||source.reason||'Fonte não encontrada',peers=translated;
   const compare=translated.length>1?`<button class="button" data-compare-episode="${ep.id}" data-old-id="${translated[translated.length-1].id}" data-new-id="${translated[0].id}">Comparar versões</button>`:'';
   return `<details class="jobline" style="display:block"><summary><b>${esc(ep.season||'')}${esc(ep.episode||'')}</b> ${esc(ep.episode_title||ep.media_filename)} · <span class="badge">${esc(summary)}</span> <span class="badge" title="Estado agregado; os problemas pertencem a versões específicas">estado por versão</span> ${sidecar} <span class="badge" title="${esc(source.reason||sourceText)}">${source.available?'✓ fonte disponível':esc(source.status||'fonte')}</span></summary><div class="record-actions" style="justify-content:flex-start;margin:8px 0"><button class="button" data-audit-episode="${ep.id}">Auditar</button>${pref&&ep.retranslation_available?`<button class="button warn" data-retranslate-episode="${ep.id}" title="${esc(sourceText)}">Retraduzir</button>`:''}${compare}</div>${!source.available?`<div class="muted" style="margin:5px 0">Fonte: ${esc(sourceText)}</div>`:''}${rs.length?rs.map(record=>versionRow(record,peers,ep.preferred_record_id)).join(''):'<div class="muted">Sem legenda arquivada.</div>'}</details>`;
  }).join('');
  $('archiveDetails').innerHTML=header+episodes;
  $('archiveDetails').querySelectorAll('[data-audit-episode]').forEach(button=>button.onclick=async()=>{try{await api('/audit/episodes/'+button.dataset.auditEpisode,{method:'POST'});await openArchiveSeries(id)}catch(e){alert(e.message)}});
  $('archiveDetails').querySelectorAll('[data-retranslate-episode]').forEach(button=>button.onclick=()=>retranslate([Number(button.dataset.retranslateEpisode)],false));
  $('archiveDetails').querySelectorAll('[data-details-record]').forEach(button=>button.onclick=()=>showVersionDetails(Number(button.dataset.detailsRecord)));
  $('archiveDetails').querySelectorAll('[data-publish-record]').forEach(button=>button.onclick=()=>publishRecord(Number(button.dataset.publishRecord)));
  $('archiveDetails').querySelectorAll('[data-compare-episode],[data-compare-old]').forEach(button=>button.onclick=()=>showComparison(button.dataset.oldId||button.dataset.compareOld,button.dataset.newId||button.dataset.compareNew));
 }catch(e){if(details)details.textContent=t('library.detailUnavailable');}
}
$('closeVersionDetails').onclick=()=>{$('versionDetailsDialog').close?.();$('versionDetailsDialog').removeAttribute('open')};$('versionDetailsDialog').addEventListener('click',event=>{if(event.target===$('versionDetailsDialog'))$('versionDetailsDialog').close?.()});

